export const meta = {
  name: 'slices45-design',
  description: 'Plan telelean slice 4 (the transform window) and slice 5 (references): 3 read-only designers, 2 synthesizers writing the plans to the scratchpad',
  phases: [{ title: 'Design' }, { title: 'Synthesize' }],
}
const R = '/home/zhengyew/telelean'
const S = '/tmp/claude-1000/-home-zhengyew-telelean/20626c17-0334-4498-ad86-9dc24b7010ed/scratchpad'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const AP = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/02_autopilot_decisions.md'
const P1 = R + '/docs/slice1-plan.md'
const P2 = R + '/docs/slice2-plan.md'
const P3 = S + '/plans/slice3-plan.md'
const OUT4 = S + '/plans/slice4-plan.md'
const OUT5 = S + '/plans/slice5-plan.md'
const AUDIT = R + '/verbatim_prompt_log/bundle_21/subagent_reports/spec_coverage_audit/coverage_audit.md'
const U20 = R + '/verbatim_prompt_log/bundle_20/prompt20.md'
const U21M = R + '/verbatim_prompt_log/bundle_21/prompt21_midturn.md'
const SAFETY = `SAFETY AND RESOURCE RULES (mandatory): READ-ONLY everywhere except the ONE file your task names (in a scratch directory). Never change git state (read-only git is fine). No network, no installs, no Claude CLI, no builds, no tests, no Lean, no tsc/vitest: other agents are building slice 2 in the same working tree right now, so the code is in flux. Never touch ${R}/packages/extension/dist or out. Never send, post, upload or publish anything.`
const CONTEXT = `Context: telelean (${R}) is a VS Code extension (packages/core, runner, extension, webview) that shows a user's beliefs as cards backed by Lean 4 files; Claude formalises and proves through the user's Claude Code CLI; a non-LLM gate decides what counts. Spec v4.1: ${SPEC}. Autopilot decisions: ${AP} (AP-n). The build has five slices: 1 the board (DONE, ${P1} and code); 2 the review list (plan ${P2}, final; being built now; its §8 records builders' decisions); 3 FROZEN (plan ${P3}, reviewed and amended; not yet built); 4 the TRANSFORM WINDOW; 5 REFERENCES. A coverage audit (${AUDIT}) mapped all 873 spec requirements; its section "Scope of slices 4 and 5" lists EXACTLY what slices 4 and 5 must cover (every for-slice4/for-slice5 row, the follow-ups G4/G5/G6, D2-13, D2-15, D3-1, D3-43's fallback, D3-49, and the rows that need references first) — your design must cover every item there or log a decision that narrows it. The user's own words outrank everything: ${U20} (the turn-20 specification: TRANSFORM, DECLINE OPTIONS, REFERENCE SYSTEM, INITIATING EDIT SESSIONS) and ${U21M} (mid-turn answers, especially D6: "search by sentence"). SIMPLICITY DIRECTIVE: slice 2's plan had to be simplified late (AP-24) and slice 3's needed many review rounds; design for the simplest SOUND mechanism, reuse slice 2's and slice 3's machinery (sessions, stages, review items, the reducer, judgeState, the freeze table, the session stack, the end confirmation), prefer refusing over repairing, and log every narrowing as an AUTOPILOT DECISION with its alternative and reversal. Constraints: tests never call real Claude (FakeBackend); the user's installed extension runs from packages/extension/dist (never built except at verified slice ends); tests single-worker under memory caps.`
const DESIGN_SCHEMA = { type: 'object', properties: { summary: { type: 'string' }, current_state: { type: 'string' }, design: { type: 'string', description: 'data model, contracts (TypeScript types), algorithms, protocol messages, persistence, UI' }, sub_slices: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, scope: { type: 'string' }, files: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' }, risk: { type: 'string' } }, required: ['id', 'scope', 'files', 'tests'] } }, open_questions: { type: 'array', items: { type: 'string' } }, safety_notes: { type: 'array', items: { type: 'string' } }, coverage: { type: 'array', items: { type: 'string', description: 'each audit row for your area and where your design covers it (or the decision that narrows it)' } } }, required: ['summary', 'current_state', 'design', 'sub_slices', 'open_questions', 'safety_notes', 'coverage'] }

phase('Design')
const lenses = [
  { key: 'slice4-engine', text: `YOUR AREA: SLICE 4's ENGINE AND CHECKS (core + runner). The transform: ES-3 sessions started by "Transform cards…" (the provisional session, the non-selected cards session-frozen — where slice 3's session-start freeze hooks become real, D3-1), transforms queued during a session (ES-9 b3, RV-9 b2, RV-12 b1), drafts and fields (TR-1..TR-6, TR-9, TR-10, the trash TR-3, fuzzy and open fields TR-4, copied cards and S11), kind changes in the window (TR-11, CF-4, §14 item 10), freezes (FZ-3 2e: your edit becomes the frozen value via slice 3's revalue hook; FZ-7 reason 4 'transform'), Claude's part (TR-7 "Claude may add cards" and plain vocabulary; TR-8 instructions; TR-15: the needs-Claude test, direct application outside a session as one Undo step with TR-12's checks only, application at Submit inside one, copied content stays Claude's, follow-on edits count as yours), checks and safety (TR-12 and S10: typed Lean is checked; TR-13 dependents and S9's other half; TR-14 and S8: transform steps write no proofs, a broken proof becomes a Proof broken item reusing slice 3's kind and mark_proof_broken), decline routes (DO-2 Decline → Transform; RV-8 b2; D2-13's "Ask me instead" becoming a Transform decline), D2-15 (Shaky steps: whether slice 4 lifts it), the B.3/Appendix B baseline for transforms, RV-7 b5, RV-5 b3, persistence (ES-6: drafts survive a reload), Undo (UN-4 4a/4b), and the follow-ups G4 (S9 dependents), G5 (a typed sentence becomes yours), G6 (TR-11's impact names the frozen arrows). Read: the spec §8 (TR-*), §7, §9-§12, Appendix A/B; the slice-2 plan's contracts and session engine; the slice-3 plan's freeze table, hooks (§3.12) and decisions; core/src/review/*, core/src/edit/*, runner/src/run/manager.ts.` },
  { key: 'slice4-ui', text: `YOUR AREA: SLICE 4's TRANSFORM WINDOW UI AND PROTOCOL (webview + extension host). The window (opening from "Transform cards…" in the Context Menu, CM-3 b1b, CM-4 row 3; from a Decline → Transform; from the review list), its layout of draft cards and fields, fuzzy/open fields and their look, new and copied cards, the trash (TR-3), the kind control (TR-11 with its impact list naming frozen arrows, G6), the "Claude may add cards" checkbox (TR-7a) and the Instructions box (TR-8; # references there come in slice 5: hook), Submit transform / Cancel and their confirmations, the session banner "Everything except the selected cards is frozen" (FZ-11 5a), freezing inside the window (FZ-9 para 1), text fields keeping their own undo (UN-4 4b) vs the session stack (UN-4 4a), drafts surviving reload (ES-6), EN-2's "what you typed is shown separately", the protocol messages with validators, the store, and tests (webview unit, extension unit, Playwright with the mock host). Read: the spec §6, §8, §11, §12; the slice-2 plan §5 (the review UI being built) and §2.4; the slice-3 plan §4 (freeze UI); the slice-1 board code (packages/webview/src/board/*, header/*, dialogs/*, state/store.ts).` },
  { key: 'slice5-refs', text: `YOUR AREA: SLICE 5, REFERENCES (all packages). RF-1 (the # dropdown in sentence and Why fields; chips that reveal their target), RF-2 (stable ids that are NEVER reused — today card ids are sentence slugs from core/markup/ids.ts slugOf, so a deleted card's id comes back for a new card with the same sentence: design the id scheme change and its migration of existing files, compatible with slice 3's freeze records keyed by card id (D3-16) and slice 2's item keys; the current name or "deleted card"; the target's sentence in Lean docstrings and in everything Claude reads), RF-3 (no dropdown in Lean fields; Esc leaves a plain #), RF-4 (no short numbers; search by sentence — the user's D6 answer; the webview has no sentence search today), CM-4 row 10 (Copy reference), FZ-4 b2 / RF-5a / S12 (references hold their targets: slice 3's heldFields() hook returns [] until now), RF-5b (TR-13 warns about references: needs slice 4), ES-9 b2 (copy references stays possible during a session), and slice 4's reference hooks (TR-4 fuzzy Dependencies as a list of # references, TR-8 # in instructions, TR-10c other subjects' vocabulary can be referenced, TR-2c new ids respect RF-2). Read: the spec §13 (RF-*), §2 CF-1, §5 FZ-4, Part 3 S12; core/src/markup/* (parser, ids, values), core/src/model.ts; the slice-3 plan's freeze addressing; the webview's text fields.` },
]
const designs = await parallel(lenses.map((l) => () => agent(`${SAFETY}\n\n${CONTEXT}\n\n${l.text}\n\nBe concrete: name files, functions, types and messages; give TypeScript type sketches for new contracts; reuse what exists and what slices 2 and 3 build. Propose sub-slices for your area (each buildable and testable by one agent, in dependency order). List open questions with your recommended answer and the alternative (the integrator decides on autopilot). Note every safety property and how it is tested. In "coverage", map every audit row of your area.`, { label: `design:${l.key}`, phase: 'Design', schema: DESIGN_SCHEMA })))
log(`designs: ${designs.filter(Boolean).length}/3`)
const d4 = designs.filter(Boolean).filter((d, i) => true)
phase('Synthesize')
const synthPrompt = (n, OUT, which) => `${SAFETY} EXCEPTION: you write exactly ONE new file, ${OUT} (create it; nothing else anywhere).\n\n${CONTEXT}\n\nWrite the slice-${n} implementation plan as ${OUT}, in the style and structure of ${P2} and ${P3} (read their sections 0, 1, 2 and 7 first), lean: at most about 900 lines for slice 4 and 500 for slice 5. Sections: 0 rules for everyone (as slices 2/3); 1 order of work (sub-slices named ${n}a, ${n}b, …; each small enough for one builder agent, each ending compiling with unit tests passing; say what each contains and which spec clauses and audit rows it implements); 2 contracts decided precisely (types, persistence and migrations, protocol messages with validators, tools, gate rules and their messages for Claude), written against the slice-2 and slice-3 contracts; 3 design; 4 UI; 5 Undo and persistence; 6 tests per sub-slice, with FakeBackend cheat scenarios; 7 decisions (D${n}-1, … each "AUTOPILOT DECISION:" with its alternative and reversal); 8 change log (empty); 9 a coverage table: every audit row assigned to slice ${n} and where the plan covers it. Resolve every conflict and decide every open question (minimal, sound, consistent with the user's words). Return a short summary: the sub-slice list, the decisions (one line each), and anything unresolved.\n\n=== DESIGNS (${which}) ===\n${JSON.stringify(designs.filter(Boolean).filter((d) => which.split(',').some((w) => (d.summary + d.design).toLowerCase().includes(w))).length ? designs.filter(Boolean) : designs.filter(Boolean), null, 1)}`
const plans = await parallel([
  () => agent(synthPrompt(4, OUT4, 'transform,window'), { label: 'synthesize:slice4', phase: 'Synthesize' }),
  () => agent(synthPrompt(5, OUT5, 'reference'), { label: 'synthesize:slice5', phase: 'Synthesize' }),
])
return { designs, plans }
